#!/bin/sh
# Writes container-appropriate Gradle settings into the (volume-backed) Gradle user home on first start.
# The user-home file overrides the project's gradle.properties for the same keys.
# Delete ~/.gradle/gradle.properties in the container and restart to regenerate it.
set -e
props="${GRADLE_USER_HOME:-$HOME/.gradle}/gradle.properties"
if [ ! -f "$props" ]; then
  mkdir -p "$(dirname "$props")"
  cat > "$props" <<'PROPS'
# Generated by container-init.sh -- sized for a container capped at 6 GB / 4 CPUs.
# Kotlin compiles in-process (set by the project), so it shares this heap.
org.gradle.jvmargs=-Xmx3g -XX:MaxMetaspaceSize=768m -Dfile.encoding=UTF-8
org.gradle.workers.max=4
org.gradle.parallel=true
kotlin.daemon.jvm.options=-Xmx1g
PROPS
fi
exec "$@"
